        if (!keys || !vaultedKeys.has(keys.join(".")) || collection) add(leaf);
      }
      // A name-flagged field the resource schema cannot vault is stripped too.
      for (const path of vaultableOf(writer)) {
        if (!vaultedKeys.has(path.join("."))) {
          add(path.map((k) => ({ k })));
        }
      }
      entry.strip = strip;
    }
  }
  return plan;
}

