// Audit: sensitive marks in resource schemas that swamp's resource-output
// walk (extractSensitiveFields) does not reach, so the value is persisted in
// plaintext. Runs with swamp's own import map so the walk is swamp's code.
// usage: deno run -A --config deno.json audit_sensitive.ts <model.ts>...
import { extractSensitiveFields } from "./src/domain/models/sensitive_field_extractor.ts";

type Any = { _zod?: { def?: Record<string, unknown> } };

function meta(s: Any): Record<string, unknown> | undefined {
  // zod v4 keeps the registry on globalThis, shared across zod copies
  // deno-lint-ignore no-explicit-any
  const reg = (globalThis as any).__zod_globalRegistry;
  return reg?.get?.(s);
}

// Every path at which a schema node carries sensitive meta, through any
// container. Array elements are written as [], record values as {}, union
// options as |n.
function deep(s: Any, path: string, out: Set<string>, seen: Set<unknown>) {
  if (!s || typeof s !== "object" || seen.has(s)) return;
  seen.add(s);
  if (meta(s)?.sensitive) out.add(path);
  const d = s._zod?.def ?? {};
  const t = d.type as string;
  const child = (x: unknown, p: string) => deep(x as Any, p, out, seen);
  if (t === "object") {
    const shape = typeof d.shape === "function" ? (d.shape as () => object)() : d.shape;
    for (const [k, v] of Object.entries(shape ?? {})) child(v, path ? `${path}.${k}` : k);
    if (d.catchall) child(d.catchall, `${path}.*`);
  } else if (t === "array") child(d.element, `${path}[]`);
  else if (t === "record" || t === "map") child(d.valueType, `${path}{}`);
  else if (t === "union") (d.options as unknown[]).forEach((o, i) => child(o, `${path}|${i}`));
  else if (t === "intersection") { child(d.left, path); child(d.right, path); }
  else if (t === "tuple") (d.items as unknown[]).forEach((o, i) => child(o, `${path}[${i}]`));
  else if (t === "pipe") { child(d.in, path); child(d.out, path); }
  else if (t === "lazy") child((d.getter as () => unknown)(), path);
  else for (const k of ["innerType", "schema"]) if (d[k]) child(d[k], path);
}

let findings = 0;
for (const file of Deno.args) {
  let mod;
  try { mod = await import(`file://${file}`); } catch (e) {
    console.log(`LOADFAIL ${file}: ${(e as Error).message.split("\n")[0]}`); continue;
  }
  const model = mod.model;
  if (!model?.resources) continue;
  for (const [spec, def] of Object.entries(model.resources as Record<string, { schema: Any; sensitiveOutput?: boolean }>)) {
    if (def.sensitiveOutput) continue;
    const all = new Set<string>();
    deep(def.schema, "", all, new Set());
    // deno-lint-ignore no-explicit-any
    const reached = new Set(extractSensitiveFields(def.schema as any).map((f) => f.path));
    // A mark below a reached ancestor is covered by the ancestor's vaulting.
    const missed = [...all].filter((p) => p !== "" && !reached.has(p) &&
      ![...reached].some((r) => p.startsWith(r + ".") || p.startsWith(r + "[") || p.startsWith(r + "{") || p.startsWith(r + "|")));
    for (const p of missed) { findings++; console.log(`UNVAULTED ${file} ${spec} ${p}`); }
  }
}
console.log(`findings=${findings}`);

