import re,subprocess
files=subprocess.run(["git","ls-files","*/extensions/models/*.ts"],capture_output=True,text=True).stdout.split()
files=[f for f in files if not f.endswith("_test.ts") and "/_lib/" not in f]
for f in files:
    s=open(f).read()
    # cloudflare: stripSensitive(x, [[{each:true}, {k:...}...]]) inside list methods
    for m in re.finditer(r'(\n    (\w+): \{\n      description:[\s\S]*?)(?=\n    \w+: \{\n      description:|\n  \},\n\};)', s):
        body=m.group(1); name=m.group(2)
        paths=[]
        for sm in re.finditer(r'stripSensitive\([^,]+,\s*(\[[\s\S]*?\])\s*\)', body):
            for p in re.finditer(r'\[\{\s*"each":\s*true\s*\}((?:,\s*\{[^}]*\})*)\]', sm.group(1)):
                ks=re.findall(r'"k":\s*"([^"]+)"', p.group(1)); paths.append("[]."+".".join(ks))
        for dm in re.finditer(r'dropItemSecrets\([^,]+,\s*\[([^\]]*)\]', body):
            paths+=["[]."+x for x in re.findall(r'"([^"]+)"',dm.group(1))]
        if paths: print(f.split("/extensions")[0], name, ", ".join(sorted(set(paths))))
EOF

