p="cloudflare-codegen/main.ts"; s=open(p).read()
def rep(a,b):
    global s; assert s.count(a)==1,a[:70]; s=s.replace(a,b)
rep('import { computeModelVersion, computeUpgradesBlock } from "./lib/upgrades.ts";',
    'import {\n  computeModelVersion,\n  computeUpgradesBlock,\n  formatCode,\n} from "./lib/upgrades.ts";')
rep('''    const versionResult = await computeModelVersion(
      modelPath,
      datePrefix,
      candidateSource,
      PLACEHOLDER,
    );''','''    // Every shipped file counts, not only the model source: a README or
    // manifest template change must bump and republish the extension too.
    const extDirPlan = join(outputBase, config.name);
    const versionResult = await computeModelVersion(
      modelPath,
      datePrefix,
      candidateSource,
      PLACEHOLDER,
      [
        { path: join(modelDir, "_lib", "api.ts"), candidate: generateApiLib() },
        {
          path: join(extDirPlan, "README.md"),
          candidate: generateReadme(config, methods),
          suffix: ".md",
        },
        {
          path: join(extDirPlan, "manifest.yaml"),
          candidate: generateManifest(config, PLACEHOLDER, modelFileName),
          suffix: ".yaml",
        },
        {
          path: join(extDirPlan, "deno.json"),
          candidate: generateDenoJson(),
          suffix: ".json",
        },
        {
          path: join(extDirPlan, "LICENSE.md"),
          candidate: generateLicense(),
          suffix: ".md",
        },
      ],
    );''')
rep('''    if (status === "unchanged" && !opts.version) {
      console.log(`      ↳ unchanged (${version}) — no write needed`);
      continue;
    }''','''    if (status === "unchanged" && !opts.version) {
      // Tests are not shipped, so a test-only change needs no version bump
      // and no release notes: refresh the file and leave the rest alone.
      const testPath = join(modelDir, testFileName);
      const testSource = generateTestSource(
        config,
        methods,
        modelFileName.replace(".ts", ""),
      );
      const onDisk = await Deno.readTextFile(testPath).catch(() => "");
      if (await formatCode(onDisk) !== await formatCode(testSource)) {
        console.log(
          `      ↳ unchanged (${version}) — refreshing generated tests only`,
        );
        if (!opts.dryRun) await Deno.writeTextFile(testPath, testSource);
      } else {
        console.log(`      ↳ unchanged (${version}) — no write needed`);
      }
      continue;
    }''')
open(p,"w").write(s); print("ok")
EOF
