/**
 * Git SHA of DataDog/datadog-api-client-go pinning the v2 OpenAPI spec.
 *
 * A commit is immutable, so a pinned URL always serves the same bytes. To
 * re-pin, pick a newer commit that touches the spec:
 *   gh api 'repos/DataDog/datadog-api-client-go/commits?path=.generator/schemas/v2/openapi.yaml&per_page=5'
 * then set it here, delete ../../datadog/.cache/, and run
 * `deno task generate:dry-run` to review what changes.
 */
export const SCHEMA_SHA = "b51c6bd9b54dafa35f5a794c4ebda9980ff1c270";

/** Datadog v2 OpenAPI spec location (from official API client repo) */
export const SCHEMA_URL =
  `https://raw.githubusercontent.com/DataDog/datadog-api-client-go/${SCHEMA_SHA}/.generator/schemas/v2/openapi.yaml`;

/** Where generated extensions land relative to this script */
export const OUTPUT_BASE = "../../datadog";

/** Zod version to use in generated code */
export const ZOD_VERSION = "4.6.5";

/** swamp-testing version */
export const SWAMP_TESTING_VERSION = "0.20260928.39";
const CACHE_DIR = ".cache";
/**
 * The cache name carries the pinned SHA: the bytes at a commit never change,
 * so a cached copy needs no expiry, and a copy left by another pin is never
 * read.
export async function fetchSchema(
  cacheDir?: string,
): Promise<OpenAPISpec> {
  const dir = cacheDir ?? CACHE_DIR;
  const cachePath = join(dir, CACHE_FILE);

  // Try cache first
  try {
    const cached = await Deno.readTextFile(cachePath);
    console.log(`   Using cached spec: ${cachePath}`);
    return parseYaml(cached) as unknown as OpenAPISpec;
  } catch {
    // Cache miss — proceed to fetch
  }

  console.log(
    `   Fetching Datadog v2 OpenAPI spec from GitHub at ${SCHEMA_SHA}...`,
  );
  const response = await fetch(SCHEMA_URL);
  if (!response.ok) {
    throw new Error(
      `Failed to fetch schema: ${response.status} ${response.statusText}`,
    );
  }

  const text = await response.text();

  // Write raw YAML to cache
  await Deno.mkdir(dir, { recursive: true });
  await Deno.writeTextFile(cachePath, text);
  console.log(
    `   Cached spec to ${cachePath} (${
      (text.length / 1024 / 1024).toFixed(1)
    }MB)`,
  );

  return parseYaml(text) as unknown as OpenAPISpec;
}
