/**
 * Tests for the spec pin: the spec URL and the cache name carry the pinned
 * commit, and a cached copy is served without touching the network.
 */

import { assertEquals, assertMatch, assertStringIncludes } from "@std/assert";
import { SCHEMA_SHA, SCHEMA_URL, SERVICES } from "../config.ts";
import { CACHE_FILE, fetchSchema } from "./schema_fetcher.ts";

Deno.test("config: the spec URL is pinned to a full commit SHA", () => {
  assertMatch(SCHEMA_SHA, /^[0-9a-f]{40}$/);
  assertStringIncludes(SCHEMA_URL, `/${SCHEMA_SHA}/`);
  assertEquals(SCHEMA_URL.includes("/master/"), false);
});

Deno.test("config: dora follows the renamed tag and stays on /api/v2/dora", () => {
  const dora = SERVICES.find((s) => s.name === "dora");
  assertEquals(dora?.tags, ["Delivery Performance"]);
  assertEquals(dora?.pathPrefixes, ["/api/v2/dora"]);
});

Deno.test("fetchSchema: serves the pinned spec from cache without any network call", async () => {
  assertStringIncludes(CACHE_FILE, SCHEMA_SHA);
  const dir = await Deno.makeTempDir();
  const originalFetch = globalThis.fetch;
  let fetchCalled = false;
  globalThis.fetch = () => {
    fetchCalled = true;
    throw new Error("a cached pinned spec must not be re-fetched");
  };
  try {
    await Deno.writeTextFile(
      `${dir}/${CACHE_FILE}`,
      "openapi: 3.0.0\ninfo: {title: Test, version: v2}\npaths: {}\ncomponents: {schemas: {}}\n",
    );
    const spec = await fetchSchema(dir);
    assertEquals(spec.info.title, "Test");
    assertEquals(fetchCalled, false);
  } finally {
    globalThis.fetch = originalFetch;
    await Deno.remove(dir, { recursive: true });
  }
});
